//! Publishing generated files.
//!
//! Every typegen output goes through here, so they all get the same guarantees:
//!
//! - **Atomic.** A file is written to a sibling temporary file and renamed over the target, so a
//!   reader (a bundler, an editor, `tsc --watch`) never sees half a file, and a failure leaves the
//!   previous version in place.
//! - **Unchanged bytes are not rewritten.** The target keeps its modification time, so file
//!   watchers do not rebuild for nothing.
//! - **Checkable.** [`status`] compares what generation would write with what is on disk without
//!   touching either, which is what `surrealkit typegen --check` reports.
//!
//! A configured formatter runs on a temporary sibling with the target's extension rather than on
//! the target itself, so the formatted bytes can be compared and published like any other output.

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

use anyhow::{Context, Result, bail};

/// What publishing a file did.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WriteOutcome {
	/// The file was missing or different and has been replaced.
	Written,
	/// The file already held exactly these bytes and was left alone.
	Unchanged,
}

/// How a file on disk compares with what generation would write.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FileStatus {
	/// The file holds exactly the generated bytes.
	UpToDate,
	/// The file exists with different contents.
	Stale,
	/// The file does not exist.
	Missing,
}

/// Write `bytes` to `path` atomically, creating its directory if needed. A file
/// that already holds exactly `bytes` is not rewritten.
pub fn write_atomic(path: &Path, bytes: &[u8]) -> Result<WriteOutcome> {
	if status(path, bytes)? == FileStatus::UpToDate {
		return Ok(WriteOutcome::Unchanged);
	}
	if let Some(dir) = parent_dir(path) {
		std::fs::create_dir_all(dir)
			.with_context(|| format!("creating directory {}", dir.display()))?;
	}
	let tmp = TempSibling::create(path, bytes)?;
	tmp.persist(path)?;
	Ok(WriteOutcome::Written)
}

/// Compare `bytes` with the file at `path` without modifying anything.
pub fn status(path: &Path, bytes: &[u8]) -> Result<FileStatus> {
	match std::fs::read(path) {
		Ok(existing) if existing == bytes => Ok(FileStatus::UpToDate),
		Ok(_) => Ok(FileStatus::Stale),
		Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(FileStatus::Missing),
		Err(err) => Err(err).with_context(|| format!("reading {}", path.display())),
	}
}

/// Run the formatter `command` over `bytes` as though they were the file
/// `target`, and return the formatted bytes. The target itself is not touched.
///
/// The command is split on whitespace and the file path appended as its last
/// argument, as for [`super::format_file`]. The formatter sees a sibling of
/// `target` with the same extension (`index.surrealkit-tmp-<pid>-<n>.ts`), so it
/// finds the project's configuration exactly as it would for the target. The
/// directory must exist; the caller creates it when it is about to publish.
pub fn format_bytes(command: &str, target: &Path, bytes: &[u8]) -> Result<Vec<u8>> {
	let mut parts = command.split_whitespace();
	let Some(program) = parts.next() else {
		return Ok(bytes.to_vec());
	};
	let args: Vec<&str> = parts.collect();
	let tmp = TempSibling::create(target, bytes)?;
	let status = std::process::Command::new(program)
		.args(&args)
		.arg(tmp.path())
		.status()
		.with_context(|| format!("failed to run formatter `{command}`"))?;
	if !status.success() {
		bail!("formatter `{command}` exited with {status}");
	}
	std::fs::read(tmp.path())
		.with_context(|| format!("reading formatter output {}", tmp.path().display()))
}

/// The directory `path` lives in, unless it is the current one.
fn parent_dir(path: &Path) -> Option<&Path> {
	path.parent().filter(|dir| !dir.as_os_str().is_empty())
}

/// A uniquely named file next to its eventual target, removed on drop unless it
/// has been renamed into place.
struct TempSibling {
	path: PathBuf,
	persisted: bool,
}

impl TempSibling {
	/// Create the temporary sibling of `target` and fill it with `bytes`.
	fn create(target: &Path, bytes: &[u8]) -> Result<Self> {
		use std::io::Write;

		static COUNTER: AtomicU64 = AtomicU64::new(0);
		let stem = target.file_stem().and_then(|s| s.to_str()).unwrap_or("typegen");
		let n = COUNTER.fetch_add(1, Ordering::Relaxed);
		let name = match target.extension().and_then(|e| e.to_str()) {
			Some(ext) => format!("{stem}.surrealkit-tmp-{}-{n}.{ext}", std::process::id()),
			None => format!("{stem}.surrealkit-tmp-{}-{n}", std::process::id()),
		};
		let path = match parent_dir(target) {
			Some(dir) => dir.join(name),
			None => PathBuf::from(name),
		};
		// From here on, drop removes whatever was created, including a partial write.
		let tmp = Self {
			path,
			persisted: false,
		};
		let mut file = std::fs::OpenOptions::new()
			.write(true)
			.create_new(true)
			.open(&tmp.path)
			.with_context(|| format!("creating {}", tmp.path.display()))?;
		file.write_all(bytes).with_context(|| format!("writing {}", tmp.path.display()))?;
		file.sync_all().with_context(|| format!("flushing {}", tmp.path.display()))?;
		Ok(tmp)
	}

	fn path(&self) -> &Path {
		&self.path
	}

	/// Rename the temporary file over `target`. `std::fs::rename` replaces an
	/// existing file on every supported platform, Windows included.
	fn persist(mut self, target: &Path) -> Result<()> {
		std::fs::rename(&self.path, target).with_context(|| {
			format!("moving {} into place at {}", self.path.display(), target.display())
		})?;
		self.persisted = true;
		Ok(())
	}
}

impl Drop for TempSibling {
	fn drop(&mut self) {
		if !self.persisted {
			let _ = std::fs::remove_file(&self.path);
		}
	}
}

#[cfg(test)]
mod tests {
	use super::*;

	fn entries(dir: &Path) -> Vec<String> {
		let mut names: Vec<String> = std::fs::read_dir(dir)
			.unwrap()
			.map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
			.collect();
		names.sort();
		names
	}

	#[test]
	fn writes_a_new_file_and_its_directory() {
		let tmp = tempfile::TempDir::new().unwrap();
		let path = tmp.path().join("nested/dir/schema.json");
		assert_eq!(write_atomic(&path, b"{}\n").unwrap(), WriteOutcome::Written);
		assert_eq!(std::fs::read(&path).unwrap(), b"{}\n");
		assert_eq!(entries(&tmp.path().join("nested/dir")), vec!["schema.json"]);
	}

	#[test]
	fn identical_bytes_are_not_rewritten() {
		let tmp = tempfile::TempDir::new().unwrap();
		let path = tmp.path().join("index.ts");
		write_atomic(&path, b"a\n").unwrap();
		let before = std::fs::metadata(&path).unwrap().modified().unwrap();
		// Make a rewrite observable even on coarse-grained filesystem clocks.
		std::thread::sleep(std::time::Duration::from_millis(1100));
		assert_eq!(write_atomic(&path, b"a\n").unwrap(), WriteOutcome::Unchanged);
		assert_eq!(std::fs::metadata(&path).unwrap().modified().unwrap(), before);

		assert_eq!(write_atomic(&path, b"b\n").unwrap(), WriteOutcome::Written);
		assert_eq!(std::fs::read(&path).unwrap(), b"b\n");
		assert_eq!(entries(tmp.path()), vec!["index.ts"], "no temporary file is left behind");
	}

	#[test]
	fn a_failed_write_keeps_the_previous_file_and_leaves_no_temporary() {
		let tmp = tempfile::TempDir::new().unwrap();
		// The target is a non-empty directory, so the final rename must fail.
		let path = tmp.path().join("index.ts");
		std::fs::create_dir(&path).unwrap();
		std::fs::write(path.join("keep"), "x").unwrap();
		let err = write_atomic(&path, b"new\n").unwrap_err();
		assert!(format!("{err:#}").contains("index.ts"), "{err:#}");
		assert_eq!(entries(tmp.path()), vec!["index.ts"], "the temporary file was removed");
		assert_eq!(std::fs::read_to_string(path.join("keep")).unwrap(), "x");
	}

	#[test]
	fn status_reports_missing_stale_and_up_to_date() {
		let tmp = tempfile::TempDir::new().unwrap();
		let path = tmp.path().join("schema.json");
		assert_eq!(status(&path, b"x").unwrap(), FileStatus::Missing);
		std::fs::write(&path, "y").unwrap();
		assert_eq!(status(&path, b"x").unwrap(), FileStatus::Stale);
		assert_eq!(status(&path, b"y").unwrap(), FileStatus::UpToDate);
	}

	#[test]
	fn temporary_siblings_keep_the_extension_and_are_unique() {
		let tmp = tempfile::TempDir::new().unwrap();
		let target = tmp.path().join("index.ts");
		let a = TempSibling::create(&target, b"a").unwrap();
		let b = TempSibling::create(&target, b"b").unwrap();
		assert_ne!(a.path(), b.path());
		for t in [&a, &b] {
			assert_eq!(t.path().parent(), Some(tmp.path()));
			assert_eq!(t.path().extension().and_then(|e| e.to_str()), Some("ts"));
		}
		drop(a);
		drop(b);
		assert!(entries(tmp.path()).is_empty(), "dropped siblings are removed");
	}

	#[test]
	fn an_empty_formatter_command_returns_the_input() {
		let tmp = tempfile::TempDir::new().unwrap();
		let out = format_bytes("  ", &tmp.path().join("index.ts"), b"x").unwrap();
		assert_eq!(out, b"x");
	}

	#[test]
	fn a_missing_formatter_is_an_error_and_cleans_up() {
		let tmp = tempfile::TempDir::new().unwrap();
		let err = format_bytes("surrealkit-no-such-formatter-xyz", &tmp.path().join("a.ts"), b"x")
			.unwrap_err();
		assert!(format!("{err:#}").contains("surrealkit-no-such-formatter-xyz"), "{err:#}");
		assert!(entries(tmp.path()).is_empty());
	}

	#[cfg(unix)]
	#[test]
	fn the_formatter_rewrites_a_sibling_not_the_target() {
		let tmp = tempfile::TempDir::new().unwrap();
		let script = tmp.path().join("fmt.sh");
		std::fs::write(&script, "#!/bin/sh\nprintf '// formatted\\n' >> \"$1\"\n").unwrap();
		let mut perms = std::fs::metadata(&script).unwrap().permissions();
		std::os::unix::fs::PermissionsExt::set_mode(&mut perms, 0o755);
		std::fs::set_permissions(&script, perms).unwrap();

		let target = tmp.path().join("index.ts");
		std::fs::write(&target, "old\n").unwrap();
		// Through `sh`: executing a file this process just wrote can fail with ETXTBSY
		// while another test thread forks.
		let command = format!("sh {}", script.display());
		let out = format_bytes(&command, &target, b"new\n").unwrap();
		assert_eq!(out, b"new\n// formatted\n");
		assert_eq!(std::fs::read_to_string(&target).unwrap(), "old\n", "target untouched");
		assert_eq!(entries(tmp.path()), vec!["fmt.sh", "index.ts"]);
	}

	#[cfg(unix)]
	#[test]
	fn a_failing_formatter_is_an_error() {
		let tmp = tempfile::TempDir::new().unwrap();
		let script = tmp.path().join("fail.sh");
		std::fs::write(&script, "#!/bin/sh\nexit 3\n").unwrap();
		let mut perms = std::fs::metadata(&script).unwrap().permissions();
		std::os::unix::fs::PermissionsExt::set_mode(&mut perms, 0o755);
		std::fs::set_permissions(&script, perms).unwrap();
		let command = format!("sh {}", script.display());
		let err = format_bytes(&command, &tmp.path().join("a.ts"), b"x").unwrap_err();
		assert!(format!("{err:#}").contains("exited with"), "{err:#}");
		assert_eq!(entries(tmp.path()), vec!["fail.sh"]);
	}
}
